import React, { useState, useEffect } from "react";
import ChartistGraph from "react-chartist";
import { Card, Container, Row, Col, Form } from "react-bootstrap";
import "chartist/dist/chartist.min.css";

/* ================= STYLE ================= */
const themeStyle = `
.chart-scroll { overflow-x: auto; overflow-y: hidden; }

.history-header {
  background: linear-gradient(87deg, #5e72e4 0, #825ee4 100%);
  border-radius: 8px 8px 0 0;
  padding: 20px;
}

.history-header .card-title {
  color: white;
  margin: 0;
  font-weight: bold;
  font-size: 1.25rem;
}

.form-select {
  border-radius: 12px;
  padding: 10px 18px;
  box-shadow: 0 1px 3px rgba(0,0,0,.08);
}

.form-label {
  font-weight: 700;
  color: #5e72e4;
  font-size: .75rem;
  text-transform: uppercase;
}

.card {
  border: none;
  box-shadow: 0 0 2rem rgba(136,152,170,.15);
  border-radius: .75rem;
}
`;

/* ================= AGGREGATE ================= */
// API ส่งมาเป็นทุก 5 นาที
const BASE_INTERVAL = 5;

const aggregateByInterval = (labels, data, interval) => {
  const groupSize = interval / BASE_INTERVAL;
  const newLabels = [];
  const newData = [];

  for (let i = 0; i < labels.length; i += groupSize) {
    const chunk = data.slice(i, i + groupSize);
    const sum = chunk.reduce((a, b) => a + b, 0);

    newLabels.push(labels[i]);
    newData.push(sum);
  }

  return { labels: newLabels, series: [newData] };
};

/* ================= COMPONENT ================= */
function History() {
  const now = new Date();
  const yearBE = now.getFullYear() + 543;

  const [cameraId, setCameraId] = useState("CAM01");
  const [day, setDay] = useState(now.getDate().toString());
  const [month, setMonth] = useState((now.getMonth() + 1).toString().padStart(2, "0"));
  const [year, setYear] = useState(yearBE.toString());
  const [startTime, setStartTime] = useState("07:00");
  const [endTime, setEndTime] = useState("22:00");
  const [interval, setInterval] = useState(30); // ⭐ interval กราฟ
  const [chartState, setChartState] = useState({ labels: [], series: [[]] });

  const handleSearch = async () => {
    const yearCE = parseInt(year) - 543;
    const date = `${yearCE}-${month}-${day.padStart(2, "0")}`;

    const res = await fetch(
      `http://localhost:3000/api/history?cameraId=${cameraId}&date=${date}&startTime=${startTime}&endTime=${endTime}`
    );
    const result = await res.json();

    if (result?.labels && result?.series) {
      const aggregated = aggregateByInterval(
        result.labels,
        result.series[0],
        interval
      );
      setChartState(aggregated);
    }
  };

  useEffect(() => {
    handleSearch();
  }, [cameraId, day, month, year, startTime, endTime, interval]);

  const barChartOptions = {
    height: "400px",
    axisY: { onlyInteger: true, low: 0 },
    axisX: { showGrid: false, offset: 60 },
    fullWidth: true
  };

  const drawBarLabels = (data) => {
    if (data.type === "bar") {
      data.element.attr({
        style: "stroke-width:30px;stroke:#5e72e4"
      });

      data.group.elem("text", {
        x: data.x2,
        y: data.y2 - 15,
        style: "font-size:13px;font-weight:bold;text-anchor:middle"
      }).text(data.value.y);
    }
  };

  return (
    <Container fluid className="py-4">
      <style>{themeStyle}</style>

      {/* ================= FILTER ================= */}
      <Card>
        <Card.Header className="history-header">
          <Card.Title>ค้นหาข้อมูลย้อนหลัง</Card.Title>
        </Card.Header>

        <Card.Body>
          <Row className="g-3">
            <Col md="3">
              <Form.Label>สถานี</Form.Label>
              <Form.Select value={cameraId} onChange={e => setCameraId(e.target.value)}>
                <option value="CAM01">วิศวะ</option>
                <option value="CAM02">วิทยาศาสตร์</option>
                <option value="CAM03">ศิลปศาสตร์</option>
                <option value="CAM04">PKY</option>
              </Form.Select>
            </Col>

            <Col md="3">
              <Form.Label>ช่วงเวลาแท่งกราฟ</Form.Label>
              <Form.Select value={interval} onChange={e => setInterval(+e.target.value)}>
                <option value={5}>ทุก 5 นาที</option>
                <option value={10}>ทุก 10 นาที</option>
                <option value={30}>ทุก 30 นาที</option>
                <option value={60}>ทุก 1 ชั่วโมง</option>
              </Form.Select>
            </Col>
          </Row>
        </Card.Body>
      </Card>

      {/* ================= CHART ================= */}
      {chartState.labels.length > 0 && (
        <Card className="mt-4">
          <Card.Header className="bg-transparent border-0">
            <h6 className="text-muted">Overview</h6>
            <h4>กราฟย้อนหลัง : {cameraId}</h4>
          </Card.Header>

          <Card.Body>
            <div className="chart-scroll">
              <div style={{ width: Math.max(chartState.labels.length * 70, 600) }}>
                <ChartistGraph
                  data={chartState}
                  type="Bar"
                  options={barChartOptions}
                  listener={{ draw: drawBarLabels }}
                />
              </div>
            </div>
          </Card.Body>
        </Card>
      )}
    </Container>
  );
}

export default History;
